import Foundation
import StyleToneCore
import SwiftData

/// SwiftData index row for one style profile JSON file.
///
/// The JSON file remains the source of truth (`style-profiles/{uuid}.json`).
/// This record only stores index metadata, so the potentially larger profile
/// document never has to travel through SQLite.
@Model
public final class StyleProfileRecord {
    @Attribute(.unique) public var id: UUID
    /// File name inside `style-profiles/`; always generated by the store.
    public var fileName: String
    public var schemaVersion: Int
    public var algorithmVersion: String
    public var pairCount: Int
    /// Raw value of ``ConfidenceLevel`` to keep the persisted schema primitive.
    public var confidenceRawValue: String
    public var tagKeys: [String]
    public var createdAt: Date
    public var updatedAt: Date
    public var isActive: Bool

    public init(
        id: UUID,
        fileName: String,
        schemaVersion: Int = StyleProfile.currentSchemaVersion,
        algorithmVersion: String = StyleProfile.currentAlgorithmVersion,
        pairCount: Int,
        confidence: ConfidenceLevel,
        tagKeys: [String],
        createdAt: Date,
        updatedAt: Date,
        isActive: Bool
    ) {
        self.id = id
        self.fileName = fileName
        self.schemaVersion = schemaVersion
        self.algorithmVersion = algorithmVersion
        self.pairCount = max(0, pairCount)
        self.confidenceRawValue = confidence.rawValue
        self.tagKeys = tagKeys
        self.createdAt = createdAt
        self.updatedAt = updatedAt
        self.isActive = isActive
    }

    /// Typed view of ``confidenceRawValue``. Not persisted.
    public var confidence: ConfidenceLevel {
        get { ConfidenceLevel(rawValue: confidenceRawValue) ?? .trial }
        set { confidenceRawValue = newValue.rawValue }
    }
}
